package ee.schimke.composeai.rcembedded.jvm

import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.remote.core.CoreDocument
import androidx.compose.remote.core.operations.Theme
import androidx.compose.ui.ImageComposeScene
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.Density
import org.jetbrains.skia.EncodedImageFormat

/**
 * A rendered frame together with the document that produced it.
 *
 * [renderRemoteDocumentToPng] returns pixels and nothing else, which is all the `rc-compare` lanes
 * ever wanted. A conformance run wants more: the corpus asserts the *laid-out component tree* in
 * most of its golds, and AndroidX's own `CoreDocument` already carries it —
 * `getRootLayoutComponent` and `Component.getX/getY/getWidth/getHeight` are public, and the
 * component class names are the very vocabulary the corpus is written in, because that is where it
 * came from.
 *
 * So this is not a second renderer. It is the same render, handing back the document it was
 * measured on so a caller can read what AndroidX decided.
 */
public class RcJvmRenderedDocument
internal constructor(public val document: CoreDocument, public val png: ByteArray)

/**
 * Renders [bytes] and returns the laid-out document alongside the frame.
 *
 * This exists for the conformance lane in `:rc-conformance`, which measures this player as the
 * **reference** the CMP player is compared against — the corpus was generated by AndroidX, so a
 * disagreement between the two says something quite different depending on which side the corpus
 * agrees with. Keep it a thin wrapper: the moment this starts differing from
 * [renderRemoteDocumentToPng] in how it sets the document up, the reference stops being a
 * reference.
 */
public fun renderRemoteDocumentForInspection(
  bytes: ByteArray,
  widthPx: Int,
  heightPx: Int,
  density: Float = 1f,
  theme: Int = Theme.LIGHT,
): RcJvmRenderedDocument {
  val document = parseDocument(bytes)
  val scene =
    ImageComposeScene(width = widthPx, height = heightPx, density = Density(density)) {
      RcPlayerJvm(document, Modifier.fillMaxSize(), theme = theme)
    }
  return try {
    val image = scene.render()
    val data =
      checkNotNull(image.encodeToData(EncodedImageFormat.PNG)) {
        "skiko declined to encode the inspected frame"
      }
    RcJvmRenderedDocument(document, data.bytes)
  } finally {
    scene.close()
  }
}
